# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64k_hansard_annual_merge_chamber_only.R
# 64k_hansard_annual_merge_chamber_only.R
#
# REPLACES 64f_hansard_annual_merge_1979_2025.R. Merges the Chamber-only
# rebuild into one consistent 1979-2025 series:
#   - speech_self_regarding_1979_2019_odell.csv (64j, Odell, Chamber-only) — 1979-2019
#   - speech_self_regarding_2020_2025.csv       (64e, live Hansard API)    — 2020-2025
#
# Only TWO sources now, not three, and both are Chamber-only throughout —
# fixes the Westminster-Hall scope discontinuity found 7 Sep
# (64i_overlap_check_multiday.R): ParlSpeech V2 (the old 1989-2019 source)
# silently included Westminster Hall debates from Nov 1999 onward while
# Odell and the API pull do not, giving the old series a hidden scope
# change right in the middle of its span. PJ, 7 Sep: chose Chamber-only
# throughout (option a) over adding Westminster Hall to the 2020-25 segment.
#
# OUTPUT: data/processed/speech_self_regarding_1979_2025.csv (OVERWRITES the
# old ParlSpeech-based version — old file's numbers are superseded, not
# archived separately, since this is a straight scope correction, not a
# competing spec; the OLD ParlSpeech-based annual file
# speech_self_regarding_annual.csv is left untouched for comparison.)

suppressMessages({library(dplyr); library(readr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT  <- .ROOT
DATA_DIR <- file.path(PROJECT, "data/processed")

odell  <- read_csv(file.path(DATA_DIR, "speech_self_regarding_1979_2019_odell.csv"), show_col_types = FALSE)
recent <- read_csv(file.path(DATA_DIR, "speech_self_regarding_2020_2025.csv"), show_col_types = FALSE)

cat(sprintf("1979-2019 (Odell, Chamber-only): %d rows, years %d-%d\n", nrow(odell), min(odell$year), max(odell$year)))
cat(sprintf("2020-2025 (Hansard API, Chamber-only): %d rows, years %d-%d\n", nrow(recent), min(recent$year), max(recent$year)))

merged <- bind_rows(odell, recent) |>
  arrange(year) |>
  mutate(source = if_else(year <= 2019, "Evan Odell dataset (parlparse), Chamber-only",
                                          "Official Hansard API (live pull), Chamber-only"))

stopifnot(nrow(merged) == 47, min(merged$year) == 1979, max(merged$year) == 2025,
          n_distinct(merged$year) == 47)

cat(sprintf("\n=== MERGED SERIES (Chamber-only throughout): %d years, %d-%d ===\n",
            nrow(merged), min(merged$year), max(merged$year)))
print(merged, n = 47)

# ---- Compare against the old (ParlSpeech-based, WestHall-mixed) series ----
old <- read_csv(file.path(DATA_DIR, "speech_self_regarding_1979_2025.csv"), show_col_types = FALSE)
comp <- merged |> select(year, new_ratio = mean_self_ratio) |>
  left_join(old |> select(year, old_ratio = mean_self_ratio), by = "year") |>
  mutate(diff = round(new_ratio - old_ratio, 4))
cat("\n=== Change vs old ParlSpeech-based series (2000-2019 is where WestHall was mixed in) ===\n")
print(comp |> filter(year >= 1998, year <= 2021), n = 24)

OUT <- file.path(DATA_DIR, "speech_self_regarding_1979_2025.csv")
write_csv(merged, OUT)
cat("\nSaved (overwrites old file):", OUT, "\n")
